					var parts=((string)text).Split(new[]{'|'}, StringSplitOptions.None);
return new {
    street = parts.Length > 0 ? parts[0].Trim() : "",
    city = parts.Length > 1 ? parts[1].Trim() : "",
    postalCode = parts.Length > 2 ? parts[2].Trim() : ""
};

					var parts = text.Split(new[]{'|'}, StringSplitOptions.None);
            return new {
                phone = parts.Length > 0 ? parts[0].Trim() : "",
                email = parts.Length > 1 ? parts[1].Trim() : ""

            };


 var parts = text.Split(new[] { '\n' }, StringSplitOptions.RemoveEmptyEntries);
return new {
  Item = parts.Length > 0 ? parts[0] : "",
  Code = parts.Length > 1 ? parts[1] : "",
  Qty = parts.Length > 2 ? parts[2] : "",
  UnitPrice = parts.Length > 3 ? parts[3] : "",
  LineTotal = parts.Length > 4 ? parts[4] : ""
};
